x,p.p.y,p.p.z,p.x.x,p.x.y,p.x.z,p.y.x,p.y.y,p.y.z,\\010        v.x,v.y,v.z,u:getDrawArgumentValue(996)*1000,u:getDrawArgumentValue(999),table.concat(values,',')))\\010    return true\\010end\\010local function tick()\\010    if failed or finished then return end\\010    local now=timer.getTime()\\010    local lead=Unit.getByName('StagedPlayback')\\010    if not lead or not lead:isExist() then\\010        failed=true;notice('FAILED: playback aircraft missing. Exit normally.');emit('FAILED missing_aircraft');return\\010    end\\010    local status=lead:getDrawArgumentValue(999)\\010    local match=math.abs(lead:getDrawArgumentValue(997)-c.token_high)<1e-8 and\\010        math.abs(lead:getDrawArgumentValue(998)-c.token_low)<1e-8\\010    if (status~=0 and not match) or status==0.75 or (now-started>2 and status~=0.125) then\\010        failed=true;emit('FAILED controller_status='..status..' matched='..tostring(match))\\010        remove_lead('failure');notice('FAILED: hold controller did not confirm. Exit normally.');return\\010    end\\010    if match and status==0.125 then\\010        if not initial_smoke then\\010            if c.smoke~=nil then lead:getController():setCommand({id='SMOKE_ON_OFF',params={value=c.smoke}})end\\010            emit(string.format('INITIAL_SMOKE,%.6f,%s',now,tostring(c.smoke)))\\010            initial_smoke=true\\010        end\\010        if c.expected then\\010            for index,value in pairs(c.expected)do\\010                local actual=lead:getDrawArgumentValue(index)\\010                -- Float/log comparison precision, not a product fidelity tolerance.\\010                if actual~=actual or math.abs(actual-value)>0.000001 then\\010                    failed=true;emit(string.format('FAILED snapshot_arg=%d expected=%.12g actual=%.12g',index,value,actual))\\010                    remove_lead('snapshot_mismatch');notice('FAILED: initial state was not retained. Exit normally.');return\\010                end\\010            end\\010